// ========== 子组件 ==========

function HeroStat({
  icon, label, value, unit, color, iconBg,
}: {
  icon: ReactNode;
  label: string;
  value: number | string;
  unit: string;
  color: string;
  iconBg: string;
}) {
  return (
    <div className={cn(
      "relative rounded-xl p-4 bg-gradient-to-br border border-white/10 overflow-hidden backdrop-blur-sm",
      color
    )}>
      <div className={cn(
        "w-8 h-8 rounded-lg bg-gradient-to-br flex items-center justify-center mb-3",
        iconBg
      )}>
        {icon}
      </div>
      <p className="text-2xl font-bold font-display tabular-nums">
        {value}<span className="text-sm text-ink-400 font-normal ml-0.5">{unit}</span>
      </p>
      <p className="text-[11px] text-ink-300 mt-0.5">{label}</p>
    </div>
  );
}

function CompactStat({
  icon, label, value, color,
}: {
  icon: ReactNode;
  label: string;
  value: number | string;
  color: string;
}) {
  return (
    <Card className="p-5 relative overflow-hidden group hover:-translate-y-0.5 transition-all duration-300">
      <div className={cn(
        "absolute -top-8 -right-8 w-24 h-24 rounded-full bg-gradient-to-br opacity-10 blur-2xl transition-opacity group-hover:opacity-20",
        color
      )} />
      <div className="relative flex items-center gap-3">
        <div className={cn(
          "w-10 h-10 rounded-xl bg-gradient-to-br flex items-center justify-center shadow-sm",
          color
        )}>
          {icon}
        </div>
        <div>
          <p className="text-2xl font-bold font-display tabular-nums text-ink-800">{value}</p>
          <p className="text-xs text-ink-500">{label}</p>
        </div>
      </div>
    </Card>
  );
}

function QuickLink({
  icon, label, desc, onClick, color,
}: {
  icon: ReactNode;
  label: string;
  desc: string;
  onClick: () => void;
  color: string;
}) {
  return (
    <button
      onClick={onClick}
      className="group w-full flex items-center gap-3 p-3 rounded-xl border border-ink-200/60 hover:border-brand-300 hover:bg-brand-50/30 transition-all duration-200 cursor-pointer text-left hover:translate-x-1"
    >
      <div className={cn(
        "w-9 h-9 rounded-lg bg-gradient-to-br flex items-center justify-center text-white shadow-sm flex-shrink-0",
        color
      )}>
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium text-ink-800">{label}</p>
        <p className="text-[11px] text-ink-400">{desc}</p>
      </div>
      <ArrowRight className="w-3.5 h-3.5 text-ink-300 group-hover:text-brand-500 group-hover:translate-x-0.5 transition-all flex-shrink-0" />
    </button>
  );
}

// 首页最近巡检列表项 —— 用 hook 解析门店名，支持用户新建门店
function HomeRecentItem({ insp, index, onClick }: { insp: Inspection; index: number; onClick: () => void }) {
  const storeName = useStoreName(insp.storeId);
  return (
    <div
      className="group flex items-center gap-3 p-3 rounded-xl hover:bg-ink-100/50 cursor-pointer transition-all duration-200 hover:translate-x-1"
      onClick={onClick}
    >
      <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-ink-100 to-ink-200 text-[11px] font-mono font-bold text-ink-500 flex items-center justify-center flex-shrink-0">
        {String(index + 1).padStart(2, "0")}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm text-ink-800 font-medium truncate">{storeName}</p>
        <p className="text-[11px] text-ink-400">{insp.templateName} · {insp.inspectTime.slice(5, 10)} · {insp.inspector}</p>
      </div>
      <div className="flex items-center gap-3">
        <span className={cn(
          "text-lg font-bold tabular-nums font-display",
          insp.score >= 90 ? "text-emerald-600" :
          insp.score >= 75 ? "text-brand-700" :
          insp.score >= 60 ? "text-amber-600" : "text-red-500"
        )}>
          {insp.score}
        </span>
        <span className={cn(
          "text-xs font-semibold tabular-nums px-2 py-0.5 rounded-md",
          insp.riskCount > 0
            ? "text-orange-600 bg-orange-50 border border-orange-200/60"
            : "text-emerald-600 bg-emerald-50 border border-emerald-200/60"
        )}>
          {insp.riskCount === 0 ? "✓ 0" : `${insp.riskCount} 项`}
        </span>
      </div>
    </div>
  );
}
